//! The stage-5 real-machine point-animation gate (parity plan › stage 5, ADR 0105):
//! point-anim.moho was generated by Moho Pro 14.4 (Lua: gen_pointanim.lua) — the gradients
//! canvas with mesh points 0, 1 and 17 keyed across frames 0/12/24 (M_Point:SetPos +
//! NewKeyframe(CHANNEL_POINT), every key linearized). Moho's own FileRender frames are the
//! truth; this test renders the imported document through the CPU oracle and compares
//! content masks exactly like the stage-2 camera gate (translation-aligned F1 on 4px cells).
//!
//! Negative control: the same document with the point tracks stripped must NOT match the
//! posed frames — the artwork stays at its frame-0 layout while Moho's points move, so the
//! aligned overlap collapses. Without this, a gate that never moved could pass on the
//! stroke baseline alone.

use anicraft_mohoproj_import::import_path;
use std::path::{Path, PathBuf};
use std::sync::Arc;

fn corpus() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("MAOHOU_FIXTURES") {
        let p = PathBuf::from(dir);
        if p.is_dir() {
            return Some(p);
        }
    }
    let beside = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../maop-corpus/maop");
    beside.is_dir().then_some(beside)
}

/// Downsampled boolean content mask (alpha > 24), cell = `step` px, any-content vote.
fn content_mask(px: &[u8], w: u32, h: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let gw = w / step;
    let gh = h / step;
    let mut m = vec![false; (gw * gh) as usize];
    for gy in 0..gh {
        for gx in 0..gw {
            let mut on = 0u32;
            for dy in 0..step {
                for dx in 0..step {
                    let a = px[(((gy * step + dy) * w + gx * step + dx) * 4 + 3) as usize];
                    if a > 24 {
                        on += 1;
                    }
                }
            }
            m[(gy * gw + gx) as usize] = on > 0;
        }
    }
    (gw, gh, m)
}

/// Best translation (within ±`range` cells) aligning `a` onto `b`, by F1 overlap.
fn best_shift(a: &[bool], b: &[bool], gw: u32, gh: u32, range: u32) -> (i64, i64, f64) {
    let (mut best_dx, mut best_dy) = (0i64, 0i64);
    let mut best_f1 = -1f64;
    let count = |dx: i64, dy: i64| -> f64 {
        let mut inter = 0u64;
        let mut na = 0u64;
        let mut nb = 0u64;
        for y in 0..gh as i64 {
            for x in 0..gw as i64 {
                let vb = b[(y as u32 * gw + x as u32) as usize];
                let ax = x - dx;
                let ay = y - dy;
                let va = ax >= 0 && ax < gw as i64 && ay >= 0 && ay < gh as i64 && a[(ay as u32 * gw + ax as u32) as usize];
                if va {
                    na += 1;
                }
                if vb {
                    nb += 1;
                }
                if va && vb {
                    inter += 1;
                }
            }
        }
        if na + nb == 0 {
            return 0.0;
        }
        2.0 * inter as f64 / (na + nb) as f64
    };
    for dy in -(range as i64)..=(range as i64) {
        for dx in -(range as i64)..=(range as i64) {
            let f1 = count(dx, dy);
            if f1 > best_f1 {
                best_f1 = f1;
                best_dx = dx;
                best_dy = dy;
            }
        }
    }
    (best_dx, best_dy, best_f1)
}

fn straight_rgba(ours: &anicraft_render::Pixmap) -> Vec<u8> {
    let mut rgba = Vec::with_capacity((ours.width * ours.height * 4) as usize);
    for p in &ours.data {
        let a = p[3];
        let un = |c: f32| if a > 0.0 { (c / a).clamp(0.0, 1.0) } else { 0.0 };
        rgba.extend_from_slice(&[(un(p[0]) * 255.0) as u8, (un(p[1]) * 255.0) as u8, (un(p[2]) * 255.0) as u8, (a * 255.0) as u8]);
    }
    rgba
}

/// The imported document rendered at `frame`, as a content mask.
fn render_mask(doc: &anicraft_doc::Document, frame: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let (w, h) = (doc.stage.width, doc.stage.height);
    let dl = anicraft_doc::evaluate(doc, frame);
    let view = anicraft_render::View { transform: anicraft_geom::Affine::IDENTITY, width: w, height: h, background: None };
    let ours = anicraft_render::render(&dl, &view).unwrap().0;
    content_mask(&straight_rgba(&ours), w, h, step)
}

#[test]
fn imported_point_animation_matches_moho_frames() {
    let Some(dir) = corpus() else {
        eprintln!("skipped: no maop-corpus beside the workspace");
        return;
    };
    let path = dir.join("point-anim.moho");
    if !path.is_file() {
        eprintln!("skipped: no point-anim.moho in the corpus");
        return;
    }
    let (doc, report) = import_path(&path).unwrap_or_else(|e| panic!("point-anim.moho: {e}"));
    // The point channels arrived: every animated Moho point rides its shape as tracks with
    // the linear keys (0/12/24), and nothing was dropped as "animated point positions".
    let mut tracks = 0usize;
    let mut animated = 0usize;
    for l in &doc.timeline(0).layers {
        for k in &l.keyframes {
            for el in &k.elements {
                if let anicraft_doc::ElementKind::Shape(s) = &el.kind {
                    tracks += s.points.len();
                    animated += s.points.iter().filter(|t| t.position.is_animated()).count();
                }
            }
        }
    }
    println!("point tracks {tracks}, animated {animated}");
    assert!(animated >= 3, "the three moved points carry channels");
    assert!(!report.skipped.contains_key("animated point positions (drawn at frame 1)"), "{:?}", report.skipped);

    // The static control: strip the tracks — the artwork stays at its rest layout.
    let mut flat = doc.clone();
    for l in flat.timeline_mut(0).layers.iter_mut() {
        let l = Arc::make_mut(l);
        for k in &mut l.keyframes {
            let k = Arc::make_mut(k);
            for el in &mut k.elements {
                let el = Arc::make_mut(el);
                if let anicraft_doc::ElementKind::Shape(s) = &mut el.kind {
                    s.points.clear();
                }
            }
        }
    }

    let (w, h) = (doc.stage.width, doc.stage.height);
    let step = 4u32;
    for (name, frame) in [("f0", 0u32), ("f6", 6), ("f12", 12), ("f18", 18), ("f24", 24)] {
        let Ok(moho_png) = std::fs::read(dir.join(format!("inputs/point-anim-{name}.png"))) else {
            eprintln!("skipped {name}: no Moho render");
            continue;
        };
        let moho = anicraft_doc::decode_png(&moho_png).unwrap();
        assert_eq!((moho.width, moho.height), (w, h), "FileRender uses the document resolution");
        let (gw, gh, m_mask) = content_mask(&moho.rgba, w, h, step);
        let (gw2, gh2, o_mask) = render_mask(&doc, frame, step);
        assert_eq!((gw, gh), (gw2, gh2));
        let (dx, dy, f1) = best_shift(&o_mask, &m_mask, gw, gh, 75);
        println!("point-anim {name}: best shift ({dx}, {dy}) cells = ({}px, {}px), aligned F1 {f1:.3}", dx * step as i64, dy * step as i64);
        // The negative control bites on the posed frames only: at frame 0 rest == pose
        // (both the keys and Moho agree), so a static render legitimately matches.
        if frame > 0 {
            let (_, _, u_mask) = render_mask(&flat, frame, step);
            let (_, _, uf1) = best_shift(&u_mask, &m_mask, gw, gh, 75);
            println!("point-anim {name}: STATIC control F1 {uf1:.3}");
            let why = format!("point-anim {name}: animated F1 {f1:.3} must beat the static control {uf1:.3} — the motion is not point-borne");
            assert!(f1 > uf1 + 0.02, "{why}");
        }
        let why = format!("point-anim {name}: aligned overlap F1 {f1:.3} — the imported points do not reproduce Moho's frame");
        assert!(f1 > 0.18, "{why}");
        let why = format!("point-anim {name}: best shift ({dx}, {dy}) cells — the artwork posed to the wrong place");
        assert!(dx.abs() <= 20 && dy.abs() <= 20, "{why}");
    }
}
